import pandas as pd
import numpy as np

# Load data
df = pd.read_csv(DATASET_PATH)
adj = pd.read_csv(ADJACENCY_PATH)

# Build symmetric neighbor sets
boroughs = set(df['borough'])
neighbors = {b: set() for b in boroughs}
for _, row in adj.iterrows():
    b, n = row['borough'], row['neighbor']
    if b in neighbors:
        neighbors[b].add(n)
    else:
        neighbors[b] = {n}
    if n in neighbors:
        neighbors[n].add(b)
    else:
        neighbors[n] = {b}

# Map NO2 values
x = df.set_index('borough')['NO2_value'].to_dict()

# Iterative-R to deflate masking
S = set(boroughs)
threshold = 1.96  # two-tailed 5% significance

while True:
    # Compute differences DIFF_i = x_i - mean(x_j for j in neighbors_i ∩ S)
    DIFF = {}
    for i in S:
        neigh_i = neighbors[i] & S
        if len(neigh_i) == 0:
            neigh_mean = np.nan
        else:
            neigh_mean = np.mean([x[j] for j in neigh_i])
        DIFF[i] = x[i] - neigh_mean
    diffs = np.array(list(DIFF.values()))
    mean_D = np.mean(diffs)
    std_D = np.std(diffs, ddof=1)
    # Compute z-scores
    z = {i: (DIFF[i] - mean_D) / std_D for i in S}
    abs_z = {i: abs(z[i]) for i in S}
    # Identify region with maximum |z|
    k_max = max(S, key=lambda i: abs_z[i])
    # Stop if the most extreme isn't masking Merton
    if (k_max != 'Merton') and (abs_z[k_max] > threshold) and (abs_z[k_max] > abs_z['Merton']):
        S.remove(k_max)
    else:
        break

# Final z for Merton
z_merton = z['Merton']
if abs(z_merton) > threshold:
    classification = "OUTLIER - HIGH" if z_merton > 0 else "OUTLIER - LOW"
else:
    classification = "NOT AN OUTLIER"

print(f"FINAL ANSWER: {classification} (z = {z_merton})")
